func (c *Core) maOpenAndFillImpl(sp *MAStream, inReal []float64, optInTimePeriod, optInMAType int32, outBegIdx, outNBElement *int32, outReal []float64) RetCode {
	if len(inReal) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inReal))
	if optInTimePeriod == IntegerDefault {
		optInTimePeriod = 30
	} else if optInTimePeriod < 1 || optInTimePeriod > 100000 {
		return BadParam
	}
	if optInMAType == IntegerDefault || optInMAType == int32(MATypeDEFAULT) {
		optInMAType = int32(MATypeSMA)
	} else if optInMAType < MATypeMin || optInMAType > MATypeMax {
		return BadParam
	}
	if sameStart(outReal, inReal) {
		return BadParam
	}
	if historyLen > c.maLookback(optInTimePeriod, optInMAType) && overlaps(outReal, inReal) {
		return BadParam
	}
	if historyLen < c.maLookback(optInTimePeriod, optInMAType)+1 {
		return InsufficientHistory
	}
	if optInTimePeriod == 1 || optInMAType == int32(MATypeDISABLED) {
		sp.optInTimePeriod = optInTimePeriod
		sp.optInMAType = optInMAType
		sp.sub = nil
		sp.arm = -1
		fillLb := c.maLookback(optInTimePeriod, optInMAType)
		*outBegIdx = fillLb
		*outNBElement = historyLen - fillLb
		for fillIdx := int32(0); fillIdx < historyLen-fillLb; fillIdx++ {
			outReal[fillIdx] = inReal[fillLb+fillIdx]
		}
		sp.cur_outReal = outReal[*outNBElement-1]
		return Success
	}
	switch optInMAType {
	case int32(MATypeSMA):
		sub, r, err := c.SMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 0
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeEMA):
		sub, r, err := c.EMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 1
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeWMA):
		sub, r, err := c.WMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 2
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeDEMA):
		sub, r, err := c.DEMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 3
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeTEMA):
		sub, r, err := c.TEMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 4
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeTRIMA):
		sub, r, err := c.TRIMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 5
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeKAMA):
		sub, r, err := c.KAMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 6
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeMAMA):
		sub, r, err := c.MAMAOpenAndFill(inReal, 0.5, 0.05, outReal, make([]float64, historyLen))
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 7
		sp.cur_outReal = sub.cur_outMAMA
	case int32(MATypeT3):
		sub, r, err := c.T3OpenAndFill(inReal, int(optInTimePeriod), 0.7, outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 8
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeHMA):
		sub, r, err := c.HMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 9
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeZLEMA):
		sub, r, err := c.ZLEMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 10
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeRMA):
		sub, r, err := c.RMAOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 11
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeVIDYA):
		sub, r, err := c.VIDYAOpenAndFill(inReal, int(optInTimePeriod), int((3*optInTimePeriod+2)/4), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 12
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeALMA):
		sub, r, err := c.ALMAOpenAndFill(inReal, int(optInTimePeriod), 6.0, 0.85, outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 13
		sp.cur_outReal = sub.cur_outReal
	case int32(MATypeSSF):
		sub, r, err := c.SSFOpenAndFill(inReal, int(optInTimePeriod), outReal)
		if err != nil {
			return err.(RetCode)
		}
		*outBegIdx = int32(r.BegIdx)
		*outNBElement = int32(r.NBElement)
		sp.sub = sub
		sp.arm = 14
		sp.cur_outReal = sub.cur_outReal
	default:
		return BadParam
	}
	sp.optInTimePeriod = optInTimePeriod
	sp.optInMAType = optInMAType
	return Success
}

