func (c *Core) maOpenInternal(inReal []float64, startIdx, optInTimePeriod, optInMAType int32) (*MAStream, error) {
	sp := &MAStream{core: c}
	if retCode := c.maOpenImpl(sp, inReal, startIdx, optInTimePeriod, optInMAType); retCode != Success {
		return nil, retCode
	}
	return sp, nil
}

// MAOpen opens a live [MAStream] on a warm-up history, oldest bar first, and
// returns it with its value at the last history bar, the value [Core.MA] writes
// there.
//
// inReal is the history; the parameters are those of [Core.MA].
//
// The error is [InsufficientHistory] for a history of at most [Core.MALookback]
// bars, [OutOfRangeEndIndex] for one longer than [IndexMax]+1 bars, and
// [BadParam] for a parameter out of range.
func (c *Core) MAOpen(inReal []float64, optInTimePeriod int, optInMAType MAType) (*MAStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.maOpenInternal(inReal, 0, int32(optInTimePeriod), int32(optInMAType))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// MAOpenAndFill opens a stream as [Core.MAOpen] does and also writes the
// outputs over the whole history, as [Core.MA] writes them for bars 0 through
// len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.MALookback] values and share no
// memory with an input or another output.
//
// The errors are those of [Core.MAOpen], and [BadParam] for an output that is
// empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) MAOpenAndFill(inReal []float64, optInTimePeriod int, optInMAType MAType, outReal []float64) (*MAStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.maLookback(int32(optInTimePeriod), int32(optInMAType)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp := &MAStream{core: c}
	if retCode := c.maOpenAndFillImpl(sp, inReal, int32(optInTimePeriod), int32(optInMAType), &outBegIdx, &outNBElement, outReal); retCode != Success {
		return nil, OutRange{}, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

func (c *Core) maOpenAndFillInternal(inReal []float64, startIdx, optInTimePeriod, optInMAType int32, outBegIdx, outNBElement *int32, outReal []float64) (*MAStream, error) {
	sp := &MAStream{core: c}
	if retCode := c.maOpenAndFillInternalImpl(sp, inReal, startIdx, optInTimePeriod, optInMAType, outBegIdx, outNBElement, outReal); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func maStepTape(sp *MAStream, tape []float64, tapeBase, tapeMask int32, inReal float64) float64 {
	switch sp.arm {
	case -1:
		sp.cur_outReal = inReal
	case 0:
		sp.cur_outReal = smaStepTape(sp.sub.(*SMAStream), tape, tapeBase, tapeMask, inReal)
	case 1:
		sp.cur_outReal = emaStepTape(sp.sub.(*EMAStream), tape, tapeBase, tapeMask, inReal)
	case 2:
		sp.cur_outReal = wmaStepTape(sp.sub.(*WMAStream), tape, tapeBase, tapeMask, inReal)
	case 3:
		sp.cur_outReal = demaStepTape(sp.sub.(*DEMAStream), tape, tapeBase, tapeMask, inReal)
	case 4:
		sp.cur_outReal = temaStepTape(sp.sub.(*TEMAStream), tape, tapeBase, tapeMask, inReal)
	case 5:
		sp.cur_outReal = trimaStepTape(sp.sub.(*TRIMAStream), tape, tapeBase, tapeMask, inReal)
	case 6:
		sp.cur_outReal = kamaStepTape(sp.sub.(*KAMAStream), tape, tapeBase, tapeMask, inReal)
	case 7:
		sub := sp.sub.(*MAMAStream)
		mamaStepTape(sub, tape, tapeBase, tapeMask, inReal)
		sp.cur_outReal = sub.cur_outMAMA
	case 8:
		sp.cur_outReal = t3StepTape(sp.sub.(*T3Stream), tape, tapeBase, tapeMask, inReal)
	case 9:
		sp.cur_outReal = hmaStepTape(sp.sub.(*HMAStream), tape, tapeBase, tapeMask, inReal)
	case 10:
		sp.cur_outReal = zlemaStepTape(sp.sub.(*ZLEMAStream), tape, tapeBase, tapeMask, inReal)
	case 11:
		sp.cur_outReal = rmaStepTape(sp.sub.(*RMAStream), tape, tapeBase, tapeMask, inReal)
	case 12:
		sp.cur_outReal = vidyaStepTape(sp.sub.(*VIDYAStream), tape, tapeBase, tapeMask, inReal)
	case 13:
		sp.cur_outReal = almaStepTape(sp.sub.(*ALMAStream), tape, tapeBase, tapeMask, inReal)
	case 14:
		sp.cur_outReal = ssfStepTape(sp.sub.(*SSFStream), tape, tapeBase, tapeMask, inReal)
	}
	sp.outRangeCount++
	return sp.cur_outReal
}

func maPeekTape(sp *MAStream, tape []float64, tapeBase, tapeMask int32, inReal float64) (float64, error) {
	switch sp.arm {
	case -1:
		return inReal, nil
	case 0:
		return smaPeekTape(sp.sub.(*SMAStream), tape, tapeBase, tapeMask, inReal)
	case 1:
		return emaPeekTape(sp.sub.(*EMAStream), tape, tapeBase, tapeMask, inReal)
	case 2:
		return wmaPeekTape(sp.sub.(*WMAStream), tape, tapeBase, tapeMask, inReal)
	case 3:
		return demaPeekTape(sp.sub.(*DEMAStream), tape, tapeBase, tapeMask, inReal)
	case 4:
		return temaPeekTape(sp.sub.(*TEMAStream), tape, tapeBase, tapeMask, inReal)
	case 5:
		return trimaPeekTape(sp.sub.(*TRIMAStream), tape, tapeBase, tapeMask, inReal)
	case 6:
		return kamaPeekTape(sp.sub.(*KAMAStream), tape, tapeBase, tapeMask, inReal)
	case 7:
		v0, _, err := mamaPeekTape(sp.sub.(*MAMAStream), tape, tapeBase, tapeMask, inReal)
		return v0, err
	case 8:
		return t3PeekTape(sp.sub.(*T3Stream), tape, tapeBase, tapeMask, inReal)
	case 9:
		return hmaPeekTape(sp.sub.(*HMAStream), tape, tapeBase, tapeMask, inReal)
	case 10:
		return zlemaPeekTape(sp.sub.(*ZLEMAStream), tape, tapeBase, tapeMask, inReal)
	case 11:
		return rmaPeekTape(sp.sub.(*RMAStream), tape, tapeBase, tapeMask, inReal)
	case 12:
		return vidyaPeekTape(sp.sub.(*VIDYAStream), tape, tapeBase, tapeMask, inReal)
	case 13:
		return almaPeekTape(sp.sub.(*ALMAStream), tape, tapeBase, tapeMask, inReal)
	case 14:
		return ssfPeekTape(sp.sub.(*SSFStream), tape, tapeBase, tapeMask, inReal)
	}
	return 0, InternalError
}

func maTapeDetach(sp *MAStream) int32 {
	switch sp.arm {
	case 0:
		return smaTapeDetach(sp.sub.(*SMAStream))
	case 1:
		return emaTapeDetach(sp.sub.(*EMAStream))
	case 2:
		return wmaTapeDetach(sp.sub.(*WMAStream))
	case 3:
		return demaTapeDetach(sp.sub.(*DEMAStream))
	case 4:
		return temaTapeDetach(sp.sub.(*TEMAStream))
	case 5:
		return trimaTapeDetach(sp.sub.(*TRIMAStream))
	case 6:
		return kamaTapeDetach(sp.sub.(*KAMAStream))
	case 7:
		return mamaTapeDetach(sp.sub.(*MAMAStream))
	case 8:
		return t3TapeDetach(sp.sub.(*T3Stream))
	case 9:
		return hmaTapeDetach(sp.sub.(*HMAStream))
	case 10:
		return zlemaTapeDetach(sp.sub.(*ZLEMAStream))
	case 11:
		return rmaTapeDetach(sp.sub.(*RMAStream))
	case 12:
		return vidyaTapeDetach(sp.sub.(*VIDYAStream))
	case 13:
		return almaTapeDetach(sp.sub.(*ALMAStream))
	case 14:
		return ssfTapeDetach(sp.sub.(*SSFStream))
	}
	return 0
}
